package ais.action.master.sosial.helper;
import java.util.Date; import org.hibernate.Session; import org.hibernate.criterion.Restrictions; import ais.database.model.sosial.*;
public final class SocialReceiptService { public BuktiSetorSosial createIfMissing(Session s,SocialRequestContext c,TransaksiDonasi d){BuktiSetorSosial r=(BuktiSetorSosial)s.createCriteria(BuktiSetorSosial.class).add(Restrictions.eq("transaction",d)).setMaxResults(1).uniqueResult();if(r!=null)return r;r=new BuktiSetorSosial();r.setTenantKey(c.getTenantKey());r.setTransaction(d);r.setReceiptNumber(SocialSecurity.reference("BS"));r.setReceiptType(d.getFundType().getReceiptType());r.setTemplateVersion("SOCIAL-V1");r.setVerificationToken(SocialSecurity.token(32));r.setGeneratedAt(new Date());r.setDeliveryStatus("AVAILABLE");r.setVoided(Boolean.FALSE);r.setStatus("VALID");r.setCreatedBy(c.getActorId());s.save(r);d.setReceiptStatus("AVAILABLE");return r;} }
